typedef struct {
    mm_sound_effect sfx;
    mm_sfxhand handle;
    uint32_t start;
    uint16_t duration;
    int16_t pitch;
    bool started;
    bool playing;
} PlayingNote;
static PlayingNote playing_notes[255];
static uint8_t playing_idx;
void init_engine() {
	irqInit();

	irqSet(IRQ_VBLANK, mmVBlank);
	irqEnable(IRQ_VBLANK);
    
    mmInitDefault((mm_addr)soundbank_bin, 8);

    TM2D = 0;
    TM3D = 0;
    TM2CNT = 0x0080;
    TM3CNT = 0x0084;

    for(uint8_t i = 0; i < sizeof(playing_notes) / sizeof(playing_notes[0]); i++)
        playing_notes[i].playing = false;
}
static void add_note(mm_sound_effect sfx, uint32_t start_mibis, uint16_t duration_mibis, uint16_t pitch) {
    PlayingNote* ptr = &playing_notes[playing_idx++ % (sizeof(playing_notes) / sizeof(playing_notes[0]))];
    ptr->sfx = sfx;
    ptr->start = start_mibis;
    ptr->duration = duration_mibis;
    ptr->pitch = pitch;
    ptr->started = false;
    ptr->playing = true;
}
static mm_sound_effect find(const char* lyric) {
    for(uint16_t i = 0; i < sizeof(pitched_syllables) / sizeof(pitched_syllables[0]); i++) {
        if(!strcmp(lyric, pitched_syllables[i].name)) return (mm_sound_effect){
            { pitched_syllables[i].id },
            (int)(1.0f * (1<<10)),
            0,
            255,
            128
        };
    }
    return (mm_sound_effect){
        { SFX_A4_TE },
        (int)(1.0f * (1<<10)),
        0,
        255,
        128
    }; // safe default
};
void play_note(const char* lyric, int16_t pitch, uint32_t start_mibis, uint16_t duration_mibis) {
    char cvowel = lyric[strlen(lyric) - 1];
    const char vowel[2] = { cvowel, 0 };
    char pitched_lyric[strlen(lyric) + 5];
    strcpy(pitched_lyric, tones[pitch + 8]); strcat(pitched_lyric, "_"); strcat(pitched_lyric, lyric);
    char pitched_vowel[6];
    strcpy(pitched_vowel, tones[pitch + 8]); strcat(pitched_vowel, "_"); strcat(pitched_vowel, vowel);
    if(!strcmp(lyric, vowel)) {
        mm_sound_effect sfx = find(pitched_lyric);
        uint16_t t_vowel = CRATE(VOWEL_TIME, -12);
        uint16_t t_transition = CRATE(TRANSITION_TIME, -12);
        for(uint16_t i = 0; i < duration_mibis; i += t_vowel - t_transition * 2)
            add_note(sfx, i, duration_mibis - i < t_vowel ? duration_mibis - i : t_vowel, -12);
    } else {
        mm_sound_effect sfx_onset = find(pitched_lyric);
        uint16_t t_onset = CRATE(ONSET_TIME, -12);
        uint16_t t_vowel = CRATE(VOWEL_TIME, -12);
        uint16_t t_transition = CRATE(TRANSITION_TIME, -12);
        add_note(sfx_onset, start_mibis, duration_mibis < t_onset ? duration_mibis : t_onset, -12);
        mm_sound_effect sfx_vowel = find(pitched_vowel);
        uint32_t vowel_mibis = start_mibis + t_onset - t_transition * 2;
        uint16_t total_vowel = (duration_mibis < t_onset ? 0 : duration_mibis - t_onset) + t_transition * 3;
        for(uint16_t i = 0; i < total_vowel; i += t_vowel - t_transition * 2)
            add_note(sfx_vowel, vowel_mibis + i, total_vowel - i < t_vowel ? total_vowel - i : t_vowel, -12);
    }
}
void play_note_now(const char* lyric, int16_t pitch, uint32_t duration_mibis) {
    play_note(lyric, pitch, mibis(), duration_mibis);
}
void loop_engine() {
    uint32_t cur = mibis();
    for(uint8_t i = 0; i < sizeof(playing_notes) / sizeof(playing_notes[0]); i++) {
        PlayingNote* ptr = &playing_notes[i];
        if(!ptr->playing) continue;
        if(cur < ptr->start) continue;
        if(!ptr->started) {
            ptr->handle = mmEffectEx(&ptr->sfx);
            mmEffectRate(ptr->handle, RATE(ptr->pitch));
            ptr->started = true;
        }
        if(cur >= ptr->start + ptr->duration) {
            mmEffectCancel(ptr->handle);
            ptr->playing = false;
        }
    }
}
uint8_t get_max_new_notes() {
    uint8_t o = 0;
    for(uint8_t i = 0; i < sizeof(playing_notes) / sizeof(playing_notes[0]); i++)
        if(!playing_notes[i].playing) o++;
    return o;
}